<script>
const c=document.getElementById('c'),x=c.getContext('2d');
function fit(){c.width=innerWidth;c.height=innerHeight}
addEventListener('resize',fit);fit();

const car={x:100,y:0,vx:0,vy:0,angle:0};
const keys={};
addEventListener('keydown',e=>keys[e.key]=true);
addEventListener('keyup',e=>keys[e.key]=false);

function step(){
  const acc=0.3,turn=0.05,fric=0.98;
  if(keys.ArrowUp)car.vx+=Math.cos(car.angle)*acc,car.vy+=Math.sin(car.angle)*acc;
  if(keys.ArrowDown)car.vx-=Math.cos(car.angle)*acc,car.vy-=Math.sin(car.angle)*acc;
  if(keys.ArrowLeft)car.angle-=turn;
  if(keys.ArrowRight)car.angle+=turn;
  car.vx*=fric;car.vy*=fric;
  car.x+=car.vx;car.y+=car.vy;
}

function draw(){
  x.clearRect(0,0,c.width,c.height);
  x.save();
  x.translate(car.x,car.y);
  x.rotate(car.angle);
  x.fillStyle='#4af';
  x.fillRect(-20,-10,40,20);
  x.restore();
}

function loop(){step();draw();requestAnimationFrame(loop)}
loop();
</script>
</body>
